#include "screens.h"
void render_player(UiFramebuffer *f,App *a){/* Outside the panel is genuinely transparent video. */ui_fb_clear(f,COLOR(0,0,0,0));int y=UI_HEIGHT-190;draw_round(f,UI_SAFE_X-12,y,UI_WIDTH-2*UI_SAFE_X+24,154,10,COLOR(18,18,22,242),COLOR(18,18,22,242));draw_text(f,UI_SAFE_X+8,y+20,a->channel_changing?"Changing channel":a->playback.title[0]?a->playback.title:"Preparing playback",22,UI_INK,580);
    const char *state=a->loading?"Please wait…":a->playback.paused?"Paused":a->playback.live?"Live":"Playing";draw_text(f,UI_SAFE_X+8,y+57,state,18,a->loading?UI_MUTED:UI_ACCENT,260);long elapsed=a->playback.elapsed;char time[80];if(a->playback.duration>0)snprintf(time,sizeof(time),"%ld:%02ld / %ld:%02ld",elapsed/60,elapsed%60,a->playback.duration/60,a->playback.duration%60);else if(a->playback.live)ui_copy(time,sizeof(time),"LIVE");else snprintf(time,sizeof(time),"%ld:%02ld",elapsed/60,elapsed%60);draw_text(f,UI_WIDTH-UI_SAFE_X-text_width(time,18)-8,y+57,time,18,UI_MUTED,0);
    int width=UI_WIDTH-2*UI_SAFE_X-16;draw_round(f,UI_SAFE_X+8,y+94,width,4,2,UI_EDGE,UI_EDGE);if(a->playback.duration>0){long e=elapsed;if(e>a->playback.duration)e=a->playback.duration;int progress=(int)((int64_t)width*e/a->playback.duration);if(progress>0)draw_round(f,UI_SAFE_X+8,y+94,progress,4,2,UI_ACCENT,UI_ACCENT);}draw_text(f,UI_SAFE_X+8,y+116,a->playback.can_pause||a->playback.can_resume?"PLAY / PAUSE     STOP  Return":"STOP  Return",14,UI_MUTED,0);draw_text(f,UI_WIDTH-UI_SAFE_X-185,y+116,"BACK  Video   MENU  Home",14,UI_MUTED,0);
}
